import stationIconUrl from "../assets/icons/station.svg";
import type { Line4Data } from "../domain/model.ts";
import type { AMapApi, MapInstance, Overlay } from "../services/amap.ts";
const escape = (value: string): string => value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
export function createStationLayer(api: AMapApi, map: MapInstance, data: Line4Data): { overlays: readonly Overlay[]; destroy(): void } { const overlays = data.stations.map((station) => new api.Marker({ position: station.coordinates, anchor: "center", zIndex: 120, content: `<div class="station-marker ${station.stationType === "reserved" ? "reserved" : ""}"><img src="${escape(stationIconUrl)}" alt="" aria-hidden="true"><b>${escape(station.nameZh)}</b></div>`, title: station.nameZh })); map.add(overlays); return { overlays, destroy: () => map.remove(overlays) }; }
