import { SimulationClock, type ClockRate } from "../services/simulation-clock.ts";
export function mountSimulationControls(container: HTMLElement, clock: SimulationClock, onChange: () => void): () => void { const rates: ClockRate[] = [0, 1, 5, 10, 30, 60]; container.innerHTML = `<div class="clock-row"><strong data-clock-label>实时</strong><time data-clock-time></time></div><label>模拟时间<input type="datetime-local" step="1" data-time-input></label><div class="rates">${rates.map((rate) => `<button data-rate="${rate}">${rate}×</button>`).join("")}</div><button data-realtime>回到实时</button>`; const refresh = () => { const snapshot = clock.snapshot(); const label = container.querySelector<HTMLElement>("[data-clock-label]"); const time = container.querySelector<HTMLTimeElement>("[data-clock-time]"); if (label) label.textContent = snapshot.mode === "simulation" ? `模拟时间 · ${snapshot.rate}×` : "实时推演"; if (time) time.textContent = snapshot.now.toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false }); }; container.addEventListener("click", (event) => { const target = event.target as HTMLElement; const rate = target.closest<HTMLElement>("[data-rate]")?.dataset.rate; if (rate !== undefined) clock.setRate(Number(rate) as ClockRate); if (target.closest("[data-realtime]")) clock.returnToRealtime(); refresh(); onChange(); }); container.querySelector<HTMLInputElement>("[data-time-input]")?.addEventListener("change", (event) => { const value = (event.target as HTMLInputElement).value; if (value) { clock.setTime(new Date(value)); refresh(); onChange(); } }); refresh(); const timer = window.setInterval(refresh, 1000); return () => window.clearInterval(timer); }
