import metroIcon from "../assets/icons/metro.svg";
import type { TrainState } from "../domain/model.ts";
import type { AMapApi, MapInstance, MarkerInstance } from "../services/amap.ts";
const label = (state: TrainState): string => `${state.vehicleId}${state.tripId ? ` · ${state.tripId}` : ""}`;
const createContent = (state: TrainState, onSelect: (state: TrainState) => void): HTMLButtonElement => {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `train-marker ${state.status === "moving" ? "moving" : ""}`;
  button.setAttribute("aria-label", `查看列车 ${label(state)} 状态`);
  button.innerHTML = `<img src="${metroIcon}" alt=""><span></span>`;
  const text = button.querySelector<HTMLElement>("span");
  if (text) text.textContent = state.tripId ?? state.vehicleId;
  button.addEventListener("click", (event) => { event.stopPropagation(); onSelect(state); });
  return button;
};

export function createTrainLayer(api: AMapApi, map: MapInstance, onSelect: (state: TrainState) => void): { update(states: readonly TrainState[]): void; destroy(): void } { const markers = new Map<string, { marker: MarkerInstance; state: TrainState }>(); return { update(states) { const visible = new Set<string>(); for (const state of states) { if (!state.position) continue; visible.add(state.vehicleId); let entry = markers.get(state.vehicleId); const content = createContent(state, onSelect); if (!entry) { const marker = new api.Marker({ position: state.position, anchor: "center", zIndex: 200, content }); entry = { marker, state }; markers.set(state.vehicleId, entry); map.add(marker); } entry.state = state; entry.marker.setPosition(state.position); entry.marker.setContent?.(content); } for (const [id, entry] of markers) if (!visible.has(id)) { map.remove(entry.marker); markers.delete(id); } }, destroy() { map.remove([...markers.values()].map((entry) => entry.marker)); markers.clear(); } }; }
