import type { Line4Data } from "../domain/model.ts";
import type { AMapApi, MapInstance, Overlay } from "../services/amap.ts";
export function createRouteLayer(api: AMapApi, map: MapInstance, data: Line4Data): () => void {
  const overlays: Overlay[] = data.parts.flatMap((part) => {
    const common = { path: part.coordinates, lineJoin: "round", lineCap: "round" };
    if (part.structureType === "elevated") return [
      new api.Polyline({ ...common, strokeColor: "#E71419", strokeWeight: 10, strokeOpacity: 0.95, zIndex: 49, extData: { partId: part.id, structureType: part.structureType, role: "rails" } }),
      new api.Polyline({ ...common, strokeColor: "#FFF6F6", strokeWeight: 3, strokeOpacity: 0.96, zIndex: 50, extData: { partId: part.id, structureType: part.structureType, role: "track-gap" } }),
    ];
    return [
      new api.Polyline({ ...common, strokeColor: "#661F30", strokeWeight: 10, strokeOpacity: 0.72, zIndex: 47, extData: { partId: part.id, structureType: part.structureType, role: "tunnel-casing" } }),
      new api.Polyline({ ...common, strokeColor: "#E71419", strokeWeight: 6, strokeOpacity: 0.94, zIndex: 48, extData: { partId: part.id, structureType: part.structureType, role: "tunnel-core" } }),
    ];
  });
  map.add(overlays);
  return () => map.remove(overlays);
}
