import type { Position, RouteModel, TrainState } from "./model.ts";
import { interpolateRoute } from "./geometry.ts";
import { eventTimes, seconds, tripBounds, type DomainTimetable, type DomainTrip, type TimedEvent } from "./timetable.ts";

function anchor(locationId: string): string { return locationId === "houxi-depot" ? "jimei-software-park-north" : locationId; }
function chainage(route: RouteModel, locationId: string): number { const value = route.stationChainage.get(anchor(locationId)); if (value === undefined) throw new Error(`No route chainage for ${locationId}`); return value; }
function passengerAt(trip: DomainTrip, now: number): boolean { if (trip.classification === "revenue") return true; if (trip.classification === "non-revenue") return false; return trip.serviceSegments?.some((segment) => segment.classification === "revenue" && now >= seconds(segment.departure) && now <= seconds(segment.arrival)) ?? false; }
function timeline(trip: DomainTrip): readonly { event: TimedEvent; locationId: string; kind: string; seconds: number }[] { return trip.events.flatMap((event) => eventTimes(event).map((time) => ({ event, locationId: anchor(event.locationId), kind: time.kind, seconds: time.seconds }))).sort((a, b) => a.seconds - b.seconds); }
function withNotice(passengerService: boolean): Pick<TrainState, "passengerService" | "notice"> { return passengerService ? { passengerService } : { passengerService, notice: "本次列车不载客" }; }

function activeTripState(trip: DomainTrip, now: number, route: RouteModel): Omit<TrainState, "vehicleId" | "circulationId"> {
  const items = timeline(trip); const passenger = passengerAt(trip, now); const notice = withNotice(passenger);
  for (const event of trip.events) { if (event.arrival && event.departure && now >= seconds(event.arrival) && now < seconds(event.departure)) { const locationId = anchor(event.locationId); return { status: "dwelling", tripId: trip.tripId, locationId, position: interpolateRoute(route, chainage(route, locationId)), nextStationId: locationId, etaSeconds: 0, ...notice }; } }
  const exact = items.find((item) => item.seconds === now); if (exact) return { status: exact.kind === "arrival" ? "dwelling" : "moving", tripId: trip.tripId, locationId: exact.locationId, position: interpolateRoute(route, chainage(route, exact.locationId)), nextStationId: exact.locationId, etaSeconds: 0, ...notice };
  for (let index = 1; index < items.length; index += 1) { const from = items[index - 1]!; const to = items[index]!; if (now > from.seconds && now < to.seconds) { const start = chainage(route, from.locationId); const end = chainage(route, to.locationId); const ratio = (now - from.seconds) / (to.seconds - from.seconds); return { status: from.locationId === to.locationId ? "dwelling" : "moving", tripId: trip.tripId, ...(from.locationId === to.locationId ? { locationId: from.locationId } : {}), position: interpolateRoute(route, start + (end - start) * ratio), nextStationId: to.locationId, etaSeconds: to.seconds - now, ...notice }; } }
  const fallback = items.at(-1)!; return { status: "dwelling", tripId: trip.tripId, locationId: fallback.locationId, position: interpolateRoute(route, chainage(route, fallback.locationId)), ...notice };
}

export function calculateTrainStates(now: number, timetable: DomainTimetable, route: RouteModel): readonly TrainState[] {
  const byId = new Map(timetable.trips.map((trip) => [trip.tripId, trip]));
  return timetable.circulations.map((circulation) => {
    const trips = circulation.tripIds.map((id) => { const trip = byId.get(id); if (!trip) throw new Error(`Unknown trip ${id}`); return trip; });
    const active = trips.find((trip) => { const [start, end] = tripBounds(trip); return now >= start && now <= end; });
    if (active) return { vehicleId: circulation.vehicleId, circulationId: circulation.circulationId, ...activeTripState(active, now, route) };
    const connection = circulation.connections.find((item) => now > seconds(item.fromTime) && now < seconds(item.toTime));
    if (connection) { const locationId = anchor(connection.locationId); const status = connection.connectionType === "standby" ? "standby" : "turning"; return { vehicleId: circulation.vehicleId, circulationId: circulation.circulationId, status, locationId, position: interpolateRoute(route, chainage(route, locationId)), passengerService: false, notice: "本次列车不载客" }; }
    const first = tripBounds(trips[0]!)[0]; return { vehicleId: circulation.vehicleId, circulationId: circulation.circulationId, status: now < first ? "waiting" : "out-of-service", passengerService: false };
  });
}
