import "./styles.css";
import "./legal.css";
import "./improvements.css";
import line4Raw from "./data/line4.geojson?raw";
import { T0402_TIMETABLE } from "./data/t0402-timetable.ts";
import { readRuntimeConfig } from "./config/runtime.ts";
import { buildRoute } from "./domain/geometry.ts";
import { parseLine4Data } from "./domain/map-data.ts";
import { shanghaiDaySeconds, type DomainTimetable } from "./domain/timetable.ts";
import { calculateTrainStates } from "./domain/train-state.ts";
import { createBaseLayerController } from "./map/base-layer-control.ts";
import { createRouteLayer } from "./map/route-layer.ts";
import { createStationLayer } from "./map/station-layer.ts";
import { createTrainLayer } from "./map/train-layer.ts";
import { loadAmap } from "./services/amap.ts";
import { readClock } from "./services/clock.ts";
import { SimulationClock } from "./services/simulation-clock.ts";
import { mountDialogControl } from "./ui/dialog-control.ts";
import { mountMapControls, type TrainViewMode } from "./ui/map-controls.ts";
import { mountSimulationControls } from "./ui/simulation-controls.ts";
import { renderStatusPanel } from "./ui/status-panel.ts";
import { renderTrainDetail } from "./ui/train-detail.ts";

const root = document.querySelector<HTMLElement>("#app");
if (!root) throw new Error("Missing #app root");
root.innerHTML = `<header><div class="brand"><p class="eyebrow">AMTR · 4号线</p><h1>AMTR 4号线运行实时演示系统</h1></div><nav class="header-actions" aria-label="显示与时间控制"><button type="button" data-dialog-trigger="map-settings-dialog" aria-haspopup="dialog" aria-controls="map-settings-dialog">地图设置</button><button type="button" data-dialog-trigger="simulation-dialog" aria-haspopup="dialog" aria-controls="simulation-dialog">时间控制</button></nav><div class="disclaimer"><b>模拟位置</b><span>非 GPS 实时位置 · 非运营方实时数据</span><small id="clock-source">正在校时</small></div></header><dialog id="map-settings-dialog" class="control-dialog map-dialog" aria-labelledby="map-settings-title"><section class="dialog-card"><div class="dialog-heading"><h2 id="map-settings-title">地图与列车显示</h2><button type="button" data-close-dialog aria-label="关闭地图设置">×</button></div><div id="map-controls" class="map-toolbar" aria-label="地图显示设置"><p class="dialog-loading">正在加载地图设置…</p></div></section></dialog><dialog id="simulation-dialog" class="control-dialog simulation-dialog" aria-labelledby="simulation-title"><section class="dialog-card"><div class="dialog-heading"><h2 id="simulation-title">时间与模拟控制</h2><button type="button" data-close-dialog aria-label="关闭时间控制">×</button></div><div id="simulation" class="controls" aria-label="模拟控制"></div></section></dialog><main class="layout"><section class="map-card"><div id="map" aria-label="厦门地铁4号线地图"><div class="map-loading">正在加载地图…</div></div><details class="route-legend-module"><summary>线路结构</summary><div class="route-legend" aria-label="线路结构图例"><span><i class="elevated" aria-hidden="true"></i>高架段</span><span><i class="underground" aria-hidden="true"></i>隧道段</span></div></details><div id="map-error" class="map-error" hidden></div></section><aside id="side-dock" class="side-dock" hidden><section id="status-panel" class="panel"><h2>列车状态</h2><div id="status" class="states" aria-live="polite"></div></section></aside></main><footer><span class="footer-version">数据版本 T0402 · Asia/Shanghai</span><p class="legal">COPYRIGHT © <a href="https://github.com/BG2FOU" target="_blank" rel="noopener noreferrer"><strong>BG2FOU</strong></a> | <a href="https://beian.miit.gov.cn/" target="_blank" rel="noopener noreferrer">闽ICP备2025114531号</a></p></footer>`;

const dialogDisposers = [
  ["map-settings-dialog", "map-settings-dialog"],
  ["simulation-dialog", "simulation-dialog"],
].map(([dialogId, triggerId]) => mountDialogControl(
  document.querySelector<HTMLDialogElement>(`#${dialogId}`)!,
  document.querySelector<HTMLButtonElement>(`[data-dialog-trigger="${triggerId}"]`)!,
));

const data = parseLine4Data(JSON.parse(line4Raw));
const route = buildRoute(data);
const timetable = T0402_TIMETABLE as unknown as DomainTimetable;
const runtime = readRuntimeConfig({
  ...import.meta.env,
  ...(!import.meta.env.PROD && __AMTR_LOCAL_AMAP_KEY__ ? { VITE_AMAP_API_KEY: __AMTR_LOCAL_AMAP_KEY__ } : {}),
  ...(!import.meta.env.PROD && __AMTR_LOCAL_AMAP_SECURITY_JS_CODE__ ? { AMAP_SECURITY_JS_CODE: __AMTR_LOCAL_AMAP_SECURITY_JS_CODE__ } : {}),
});
let clockOffset = 0;
const clock = new SimulationClock(() => Date.now() + clockOffset);
const status = document.querySelector<HTMLElement>("#status")!;
const sideDock = document.querySelector<HTMLElement>("#side-dock")!;
const layout = document.querySelector<HTMLElement>(".layout")!;
let trainViewMode: TrainViewMode = "popup";
let latestStates: ReturnType<typeof calculateTrainStates> = [];
let updateMap: ((states: ReturnType<typeof calculateTrainStates>) => void) | undefined;
let refreshSelectedTrain: ((states: ReturnType<typeof calculateTrainStates>) => void) | undefined;

function update(): void {
  const now = clock.snapshot().now;
  const daySeconds = shanghaiDaySeconds(now);
  latestStates = calculateTrainStates(daySeconds, timetable, route);
  renderStatusPanel(status, latestStates, data.stations);
  updateMap?.(latestStates);
  refreshSelectedTrain?.(latestStates);
}

const destroySimulationControls = mountSimulationControls(document.querySelector<HTMLElement>("#simulation")!, clock, update);
update();
const timer = window.setInterval(update, 1_000);

async function synchronizeClock(): Promise<void> {
  const reading = await readClock({ ...(runtime.timeApiUrl ? { timeApiUrl: runtime.timeApiUrl } : {}) });
  clockOffset = reading.now.getTime() - Date.now();
  const source = document.querySelector<HTMLElement>("#clock-source");
  if (source) source.textContent = reading.source === "json-api" ? "时间源：远程校时" : reading.source === "http-date" ? "时间源：站点 HTTP Date" : "时间源：设备时间（降级）";
  update();
}
void synchronizeClock();
const syncTimer = window.setInterval(() => void synchronizeClock(), 300_000);
const onVisibility = () => { if (document.visibilityState === "visible") void synchronizeClock(); };
document.addEventListener("visibilitychange", onVisibility);

const mapError = document.querySelector<HTMLElement>("#map-error")!;
const describeError = (error: unknown): string => {
  if (error instanceof Error) return error.message;
  if (typeof error === "string") return error;
  if (error && typeof error === "object" && "message" in error && typeof error.message === "string") return error.message;
  return "未知错误";
};
loadAmap(runtime).then((api) => {
  const map = new api.Map(document.querySelector<HTMLElement>("#map")!, { zoom: 11, center: [118.19, 24.6], viewMode: "2D", resizeEnable: true });
  const baseLayers = createBaseLayerController(api, map);
  const destroyRoute = createRouteLayer(api, map, data);
  const stations = createStationLayer(api, map, data);
  const infoWindow = new api.InfoWindow({ closeWhenClickMap: true, offset: [0, -18] });
  let selectedVehicleId: string | undefined;
  const showTrain = (state: (typeof latestStates)[number]): void => {
    selectedVehicleId = state.vehicleId;
    if (trainViewMode === "sidebar") {
      document.querySelector<HTMLElement>(`[data-vehicle-id="${state.vehicleId}"]`)?.focus();
      return;
    }
    if (!state.position) return;
    infoWindow.setContent(renderTrainDetail(state, data.stations));
    infoWindow.open(map, state.position);
  };
  const trains = createTrainLayer(api, map, showTrain);
  const setTrainViewMode = (mode: TrainViewMode): void => {
    trainViewMode = mode;
    const sidebar = mode === "sidebar";
    sideDock.hidden = !sidebar;
    layout.classList.toggle("sidebar-open", sidebar);
    if (sidebar) infoWindow.close();
  };
  const destroyMapControls = mountMapControls(document.querySelector<HTMLElement>("#map-controls")!, baseLayers, setTrainViewMode);
  updateMap = (states) => trains.update(states);
  refreshSelectedTrain = (states) => {
    if (trainViewMode !== "popup" || !selectedVehicleId) return;
    const state = states.find((candidate) => candidate.vehicleId === selectedVehicleId);
    if (state?.position) infoWindow.setContent(renderTrainDetail(state, data.stations));
    else { selectedVehicleId = undefined; infoWindow.close(); }
  };
  update();
  map.setFitView(stations.overlays);
  document.querySelector<HTMLElement>(".map-loading")?.remove();
  window.addEventListener("pagehide", () => { destroyMapControls(); infoWindow.close(); trains.destroy(); stations.destroy(); destroyRoute(); map.destroy(); }, { once: true });
}).catch((error: unknown) => {
  document.querySelector<HTMLElement>(".map-loading")?.remove();
  const mapControls = document.querySelector<HTMLElement>("#map-controls");
  if (mapControls) mapControls.innerHTML = `<p class="dialog-error">地图暂不可用，无法调整底图与列车显示。</p>`;
  mapError.hidden = false;
  mapError.textContent = `地图暂不可用：${describeError(error)}。时间模拟和列车推演仍可使用。`;
});

window.addEventListener("pagehide", () => {
  window.clearInterval(timer);
  window.clearInterval(syncTimer);
  document.removeEventListener("visibilitychange", onVisibility);
  dialogDisposers.forEach((dispose) => dispose());
  destroySimulationControls();
}, { once: true });
