export interface TimedEvent { readonly locationId: string; readonly arrival?: string; readonly departure?: string; readonly pass?: string; readonly boundaryTime?: string }
export interface DomainTrip { readonly tripId: string; readonly direction: "up" | "down"; readonly circulationId: string; readonly vehicleId: string; readonly classification: "revenue" | "non-revenue" | "mixed"; readonly events: readonly TimedEvent[]; readonly serviceSegments?: readonly { readonly classification: string; readonly departure: string; readonly arrival: string }[] }
export interface DomainConnection { readonly fromTripId: string; readonly toTripId: string; readonly locationId: string; readonly fromTime: string; readonly toTime: string; readonly connectionType: string }
export interface DomainCirculation { readonly circulationId: string; readonly vehicleId: string; readonly tripIds: readonly string[]; readonly connections: readonly DomainConnection[] }
export interface DomainTimetable { readonly trips: readonly DomainTrip[]; readonly circulations: readonly DomainCirculation[] }

export function seconds(value: string): number { const match = /^(\d{2}):(\d{2}):(\d{2})$/.exec(value); if (!match) throw new Error(`Invalid time ${value}`); return Number(match[1]) * 3600 + Number(match[2]) * 60 + Number(match[3]); }
export function eventTimes(event: TimedEvent): readonly { kind: "arrival" | "departure" | "pass" | "boundary"; value: string; seconds: number }[] { const values: { kind: "arrival" | "departure" | "pass" | "boundary"; value: string; seconds: number }[] = []; if (event.arrival) values.push({ kind: "arrival", value: event.arrival, seconds: seconds(event.arrival) }); if (event.departure) values.push({ kind: "departure", value: event.departure, seconds: seconds(event.departure) }); if (event.pass) values.push({ kind: "pass", value: event.pass, seconds: seconds(event.pass) }); if (event.boundaryTime) values.push({ kind: "boundary", value: event.boundaryTime, seconds: seconds(event.boundaryTime) }); return values; }
export function tripBounds(trip: DomainTrip): readonly [number, number] { const values = trip.events.flatMap(eventTimes).map((item) => item.seconds); return [Math.min(...values), Math.max(...values)]; }
export function shanghaiDaySeconds(now: Date): number { const parts = new Intl.DateTimeFormat("en-GB", { timeZone: "Asia/Shanghai", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" }).formatToParts(now); const get = (type: string): number => Number(parts.find((part) => part.type === type)?.value ?? 0); return get("hour") * 3600 + get("minute") * 60 + get("second"); }
