import type { Station, TrainState } from "../domain/model.ts";
const STATUS: Record<TrainState["status"], string> = { waiting: "等待上线", moving: "运行中", dwelling: "停站中", turning: "折返中", standby: "备用", "out-of-service": "已下线" };
export function renderStatusPanel(container: HTMLElement, states: readonly TrainState[], stations: readonly Station[]): void { const names = new Map(stations.map((station) => [station.id, station.nameZh])); const visible = states.filter((state) => state.status !== "out-of-service"); container.innerHTML = visible.length === 0 ? `<p class="empty">当前没有上线列车</p>` : visible.map((state) => `<button class="state-card" data-vehicle-id="${state.vehicleId}"><b>${state.tripId ?? state.vehicleId}</b><span>${STATUS[state.status]}</span><small>${state.status === "dwelling" && state.locationId ? `${names.get(state.locationId) ?? state.locationId}站停站中` : state.nextStationId ? `前方 ${names.get(state.nextStationId) ?? state.nextStationId}${state.etaSeconds !== undefined ? ` · ${state.etaSeconds} 秒` : ""}` : ""}</small>${state.notice ? `<em>${state.notice}</em>` : ""}</button>`).join(""); }
